// In-browser queries over the committed harmonized evidence. The Parquet file is
// generated by scripts/build_site.py from data/harmonized/ on every site build,
// so results here always match the published downloads.
import * as duckdb from "https://cdn.jsdelivr.net/npm/@duckdb/duckdb-wasm@1.29.0/+esm";

const PARQUET_URL = "downloads/aree_evidence.parquet";
const ROW_LIMIT = 200;

const el = (id) => document.getElementById(id);
const status = el("aree-status");
const controls = ["aree-gene", "aree-stressor", "aree-tissue", "aree-study", "aree-direction", "aree-fdr"];

function fail(message, error) {
  status.textContent = message + (error && error.message ? " (" + error.message + ")" : "");
  if (error) console.error(error);
}

async function instantiate() {
  const bundle = await duckdb.selectBundle(duckdb.getJsDelivrBundles());
  const workerUrl = URL.createObjectURL(
    new Blob(['importScripts("' + bundle.mainWorker + '");'], { type: "text/javascript" })
  );
  const db = new duckdb.AsyncDuckDB(new duckdb.ConsoleLogger(duckdb.LogLevel.WARNING), new Worker(workerUrl));
  await db.instantiate(bundle.mainModule, bundle.pthreadWorker);
  URL.revokeObjectURL(workerUrl);
  return db;
}

async function download() {
  const response = await fetch(PARQUET_URL);
  if (!response.ok) throw new Error("HTTP " + response.status + " for " + PARQUET_URL);
  const total = Number(response.headers.get("Content-Length")) || 0;
  const reader = response.body.getReader();
  const chunks = [];
  let received = 0;
  for (;;) {
    const { done, value } = await reader.read();
    if (done) break;
    chunks.push(value);
    received += value.length;
    status.textContent = "Downloading evidence table… " + (received / 1e6).toFixed(1) +
      (total ? " / " + (total / 1e6).toFixed(1) : "") + " MB";
  }
  const buffer = new Uint8Array(received);
  let offset = 0;
  for (const chunk of chunks) { buffer.set(chunk, offset); offset += chunk.length; }
  return buffer;
}

function rowsOf(result) {
  return result.toArray().map((row) => row.toJSON());
}

function fmtNumber(value, digits) {
  if (value === null || value === undefined || Number.isNaN(value)) return "—";
  const n = Number(value);
  if (n !== 0 && Math.abs(n) < 1e-3) return n.toExponential(2);
  return n.toLocaleString("en-US", { maximumSignificantDigits: digits || 4 });
}

function geneCell(featureId) {
  const match = /NCBI:GeneID:(\d+)/.exec(featureId);
  if (!match) return escapeHtml(featureId);
  return '<a href="https://www.ncbi.nlm.nih.gov/gene/' + match[1] + '" target="_blank" rel="noopener">' +
    escapeHtml(featureId.replace("NCBI:GeneID:", "")) + "</a>";
}

function escapeHtml(value) {
  return String(value === null || value === undefined ? "" : value)
    .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
}

function buildFilters() {
  const where = [];
  const params = [];
  const gene = el("aree-gene").value.trim();
  if (gene) {
    where.push("(feature_id_standardized ILIKE '%' || ? || '%' OR description ILIKE '%' || ? || '%')");
    params.push(gene, gene);
  }
  for (const [id, column] of [["aree-stressor", "stressor"], ["aree-tissue", "tissue"], ["aree-study", "study_id"]]) {
    const value = el(id).value;
    if (value) { where.push(column + " = ?"); params.push(value); }
  }
  const direction = el("aree-direction").value;
  if (direction === "up") where.push("effect_size > 0");
  if (direction === "down") where.push("effect_size < 0");
  const fdr = el("aree-fdr").value;
  if (fdr) { where.push("adjusted_p_value < ?"); params.push(Number(fdr)); }
  return { clause: where.length ? " WHERE " + where.join(" AND ") : "", params };
}

function renderRows(rows) {
  const body = el("aree-results").querySelector("tbody");
  body.innerHTML = rows.map((row) => {
    const exploratory = String(row.inference_status).startsWith("Exploratory");
    const badge = exploratory
      ? '<span class="aree-badge exploratory" title="' + escapeHtml(row.inference_status) +
        ': standard errors and adjusted p-values are nominal only; excluded from pooling and significance rewards.">exploratory</span>'
      : '<span class="aree-badge" title="' + escapeHtml(row.inference_status) + '">association</span>';
    return "<tr>" +
      "<td>" + geneCell(row.feature_id_standardized) + "</td>" +
      '<td class="aree-desc" title="' + escapeHtml(row.description) + '">' + escapeHtml(row.description) + "</td>" +
      '<td><a href="studies/' + escapeHtml(row.study_id) + '.html" title="' + escapeHtml(row.study_id) + '">' +
        escapeHtml(row.bioproject) + "</a></td>" +
      "<td>" + escapeHtml(row.sample_comparison) + "</td>" +
      "<td>" + escapeHtml(row.tissue) + "</td>" +
      "<td>" + escapeHtml(row.life_stage) + "</td>" +
      "<td>" + escapeHtml(row.stressor) + "</td>" +
      '<td class="aree-num">' + fmtNumber(row.effect_size) + "</td>" +
      '<td class="aree-num">' + fmtNumber(row.standard_error, 3) + "</td>" +
      '<td class="aree-num">' + fmtNumber(row.adjusted_p_value, 3) + (exploratory ? " (nominal)" : "") + "</td>" +
      "<td>" + badge + "</td>" +
      '<td class="aree-flags" title="' + escapeHtml(row.quality_flags) + '">' + escapeHtml(row.quality_flags) + "</td>" +
      "</tr>";
  }).join("");
  el("aree-results").hidden = rows.length === 0;
}

function renderGenericTable(table, result) {
  const rows = rowsOf(result);
  const columns = result.schema.fields.map((field) => field.name);
  table.querySelector("thead").innerHTML =
    "<tr>" + columns.map((name) => "<th>" + escapeHtml(name) + "</th>").join("") + "</tr>";
  table.querySelector("tbody").innerHTML = rows.slice(0, 1000).map((row) =>
    "<tr>" + columns.map((name) => {
      const value = row[name];
      const shown = typeof value === "bigint" ? value.toLocaleString("en-US")
        : typeof value === "number" ? fmtNumber(value, 6) : escapeHtml(value);
      return "<td>" + shown + "</td>";
    }).join("") + "</tr>"
  ).join("");
  table.hidden = false;
}

async function main() {
  let connection;
  try {
    const [db, buffer] = await Promise.all([instantiate(), download()]);
    status.textContent = "Preparing the evidence table…";
    await db.registerFileBuffer("aree_evidence.parquet", buffer);
    connection = await db.connect();
    await connection.query("CREATE VIEW evidence AS SELECT * FROM parquet_scan('aree_evidence.parquet')");
  } catch (error) {
    fail("The query page could not start — your browser may block WebAssembly or the download failed. " +
      "The data remain available from the downloads above.", error);
    return;
  }

  async function distinct(column, select) {
    const result = await connection.query(
      "SELECT DISTINCT " + column + " AS value FROM evidence ORDER BY value");
    for (const row of rowsOf(result)) {
      const option = document.createElement("option");
      option.value = row.value;
      option.textContent = row.value;
      select.appendChild(option);
    }
  }

  async function run() {
    const { clause, params } = buildFilters();
    const select = "SELECT study_id, bioproject, feature_id_standardized, description, sample_comparison, " +
      "effect_size, standard_error, adjusted_p_value, tissue, life_stage, stressor, inference_status, quality_flags " +
      "FROM evidence" + clause +
      " ORDER BY adjusted_p_value ASC NULLS LAST, abs(effect_size) DESC, feature_id_standardized LIMIT " + ROW_LIMIT;
    try {
      const statement = await connection.prepare(select);
      const result = await statement.query(...params);
      await statement.close();
      const counter = await connection.prepare("SELECT count(*) AS n FROM evidence" + clause);
      const total = Number(rowsOf(await counter.query(...params))[0].n);
      await counter.close();
      const rows = rowsOf(result);
      renderRows(rows);
      el("aree-count").textContent = total.toLocaleString("en-US") + " matching records" +
        (total > rows.length ? "; showing the " + rows.length + " with the smallest adjusted p-values" : "") + ".";
    } catch (error) {
      fail("Query failed.", error);
    }
  }

  try {
    const overview = rowsOf(await connection.query(
      "SELECT count(*) AS records, count(DISTINCT study_id) AS contrasts FROM evidence"))[0];
    await distinct("stressor", el("aree-stressor"));
    await distinct("tissue", el("aree-tissue"));
    await distinct("study_id", el("aree-study"));
    status.textContent = "Ready: " + Number(overview.records).toLocaleString("en-US") +
      " evidence records across " + Number(overview.contrasts) + " study contrasts. Queries run in your browser.";
  } catch (error) {
    fail("The evidence table could not be read.", error);
    return;
  }

  let pending;
  for (const id of controls) {
    el(id).disabled = false;
    el(id).addEventListener("input", () => {
      clearTimeout(pending);
      pending = setTimeout(run, 250);
    });
  }
  el("aree-sql-run").disabled = false;
  el("aree-sql-run").addEventListener("click", async () => {
    el("aree-sql-error").textContent = "";
    try {
      renderGenericTable(el("aree-sql-results"), await connection.query(el("aree-sql").value));
    } catch (error) {
      el("aree-sql-results").hidden = true;
      el("aree-sql-error").textContent = String(error.message || error);
    }
  });
  await run();
}

main();
